var msgText = (typeof msg.payload === 'string') ? msg.payload : (msg.payload.text || '').trim();
var query = (msg.req && msg.req.query) ? msg.req.query : {};
var source = query.source ? String(query.source) : 'phone';
var ts = query.time ? Date.parse(String(query.time)) : Date.now();
if (isNaN(ts)) { ts = Date.now(); }
var EX = [
  { id: 'ppl_push_bench_flat', direction: 'push', label: '平板卧推', aliases: ['杠铃平板卧推','平板卧推','杠铃卧推','卧推'] },
  { id: 'ppl_push_bench_incline', direction: 'push', label: '上斜卧推', aliases: ['杠铃上斜卧推','上斜卧推','上斜推'] },
  { id: 'ppl_push_bench_close', direction: 'push', label: '窄距卧推', aliases: ['平板窄距卧推','窄距卧推','窄握卧推'] },
  { id: 'ppl_push_overhead_press', direction: 'push', label: '站姿推举', aliases: ['站姿杠铃推举','站姿推举','杠铃推举','推举'] },
  { id: 'ppl_push_pec_deck', direction: 'push', label: '夹胸', aliases: ['蝴蝶机夹胸','龙门架夹胸','器械夹胸','绳索夹胸','飞鸟','夹胸'] },
  { id: 'ppl_pull_deadlift', direction: 'pull', label: '硬拉', aliases: ['罗马尼亚硬拉','直腿硬拉','杠铃硬拉','硬拉'] },
  { id: 'ppl_pull_seated_row', direction: 'pull', label: '坐姿划船', aliases: ['坐姿绳索划船','坐姿器械划船','坐姿划船','绳索划船'] },
  { id: 'ppl_pull_tbar_row', direction: 'pull', label: 'T杆划船', aliases: ['T杆划船','T杠划船','T-bar划船'] },
  { id: 'ppl_pull_lat_pulldown', direction: 'pull', label: '高位下拉', aliases: ['高位下拉','宽握下拉','宽距下拉','下拉'] },
  { id: 'ppl_squat_back_squat', direction: 'squat', label: '杠铃深蹲', aliases: ['杠铃深蹲','深蹲'] },
  { id: 'ppl_squat_leg_press_hack', direction: 'squat', label: '倒蹬/哈克', aliases: ['倒蹬机','哈克深蹲','倒蹬','腿举','哈克'] },
  { id: 'ppl_squat_leg_extension', direction: 'squat', label: '腿屈伸', aliases: ['腿屈伸'] },
  { id: 'ppl_squat_leg_curl', direction: 'squat', label: '腿弯举', aliases: ['俯身腿弯举','腿弯举'] },
  { id: 'ppl_pull_barbell_curl', direction: 'pull', label: '杠铃弯举', aliases: ['EZ杠弯举','EZ杆弯举','曲杆弯举','EZ弯举','杠铃弯举','弯举'] },
  { id: 'ppl_squat_calf_raise', direction: 'squat', label: '站姿提踵', aliases: ['站姿提踵','提踵'] },
  { id: 'ppl_pull_back_extension', direction: 'pull', label: '山羊挺身', aliases: ['山羊挺身','山羊椅挺身','背屈伸','臀腿挺身','背伸展'] }
];
var aliasList = [];
EX.forEach(function (ex) { ex.aliases.forEach(function (a) { aliasList.push({ alias: a, ex: ex }); }); });
aliasList.sort(function (x, y) { return y.alias.length - x.alias.length; });
function findExAt(text, pos) {
  for (var k = 0; k < aliasList.length; k++) {
    if (text.slice(pos, pos + aliasList[k].alias.length) === aliasList[k].alias) { return aliasList[k]; }
  }
  return null;
}
var setRe = /(\d+(?:\.\d+)?)\s*(?:kg|公斤|千克)?\s*[x×*X]\s*(\d+)/g;
var setTokens = [];
var m;
while ((m = setRe.exec(msgText)) !== null) { setTokens.push({ w: parseFloat(m[1]), r: parseInt(m[2], 10), start: m.index, end: setRe.lastIndex }); }
var occ = [];
var i = 0;
while (i < msgText.length) {
  var hit = findExAt(msgText, i);
  if (hit) { occ.push({ ex: hit.ex, start: i, end: i + hit.alias.length }); i = i + hit.alias.length; }
  else { i++; }
}
var parsed = [];
for (var k2 = 0; k2 < occ.length; k2++) {
  var o = occ[k2];
  var nextStart = (k2 + 1 < occ.length) ? occ[k2 + 1].start : msgText.length;
  var sets = [];
  for (var t = 0; t < setTokens.length; t++) {
    var st = setTokens[t];
    if (st.start >= o.end && st.start < nextStart) { sets.push({ w: st.w, r: st.r }); }
  }
  if (sets.length > 0) { parsed.push({ ex: o.ex, sets: sets }); }
}
var merged = {};
parsed.forEach(function (p) {
  if (!merged[p.ex.id]) { merged[p.ex.id] = { ex: p.ex, sets: [] }; }
  merged[p.ex.id].sets = merged[p.ex.id].sets.concat(p.sets);
});
var sessionId = 's' + ts;
// === 训练时长解析（总时间，分钟）===
var durTotal = 0;
var durRe = /(?:训练时长|训练时间|训练|练了|锻炼)\s*(\d+(?:\.\d+)?)\s*(?:小时|h|hr|hrs)/g;
var mh;
while ((mh = durRe.exec(msgText)) !== null) { durTotal += parseFloat(mh[1]) * 60; }
var minRe = /(?:训练时长|训练时间|训练|练了|锻炼)\s*(\d+(?:\.\d+)?)\s*(?:分钟|min|mins|分)/g;
var mm2;
while ((mm2 = minRe.exec(msgText)) !== null) { durTotal += parseFloat(mm2[1]); }
durTotal = Math.round(durTotal);
// 方向推断：优先取"训练"关键字前最近的方向词，否则继承动作方向，否则 other
var durDirection = 'other';
var durKwPos = msgText.search(/(?:训练时长|训练时间|训练|练了|锻炼)/);
var lastDir = null;
var dirScan = /(推日|拉日|蹲日)/g;
var dm;
while ((dm = dirScan.exec(msgText)) !== null) { if (dm.index < durKwPos) { lastDir = dm[1]; } }
if (lastDir === '推日') { durDirection = 'push'; }
else if (lastDir === '拉日') { durDirection = 'pull'; }
else if (lastDir === '蹲日') { durDirection = 'squat'; }
if (durDirection === 'other') {
  var dirs = {};
  Object.keys(merged).forEach(function (id) { dirs[merged[id].ex.direction] = true; });
  var dirKeys = Object.keys(dirs);
  if (dirKeys.length === 1) { durDirection = dirKeys[0]; }
}
// === PR 检验模式判定（消息以 PR/测试 开头）===
var compact2 = msgText.replace(/\s+/g, '');
var isPR = /^pr/i.test(compact2) || /^测试/i.test(compact2);
var measurements = [];
var actionCount = 0;
var setCount = 0;
Object.keys(merged).forEach(function (id) {
  var g = merged[id];
  g.sets.forEach(function (s, idx) {
    var tags = { direction: g.ex.direction, exercise: g.ex.label, set_index: String(idx + 1), session_id: sessionId, source: source };
    if (isPR) { tags.type = 'pr'; tags.weight_kg = String(s.w); }
    measurements.push({
      measurement: isPR ? 'ppl_pr_test' : g.ex.id,
      fields: isPR ? { weight_kg: s.w, max_reps: s.r } : { weight_kg: s.w, reps: s.r },
      tags: tags,
      timestamp: ts
    });
  });
  actionCount++;
  setCount += g.sets.length;
});
if (durTotal > 0) {
  measurements.push({
    measurement: 'ppl_duration_min',
    fields: { minutes: durTotal },
    tags: { direction: durDirection, session_id: sessionId, source: source },
    timestamp: ts
  });
}
// === 晨脉解析（静息心率，每天一次；关键字：晨脉/静息心率/早起心率/晨起心率/早晨心率）===
var hrRe = /(?:晨脉|静息心率|早起心率|晨起心率|早晨心率|resting)\s*(\d+(?:\.\d+)?)\s*(?:次|bpm|BPM)?/g;
var hrCount = 0;
var mh2;
while ((mh2 = hrRe.exec(msgText)) !== null) {
  measurements.push({
    measurement: 'ppl_morning_hr',
    fields: { bpm: parseFloat(mh2[1]) },
    tags: { session_id: sessionId, source: source },
    timestamp: ts
  });
  hrCount++;
}
// === 意象训练解析（动作意象实验打卡；关键字：意象/心理预演/imagery）===
var imgCount = 0;
if (/意象|意念|心理预演|imagery/i.test(msgText)) {
  measurements.push({
    measurement: 'ppl_imagery',
    fields: { done: 1 },
    tags: { session_id: sessionId, source: source },
    timestamp: ts
  });
  imgCount = 1;
}

// === 底座习惯解析（第1-4周底座；早上录入，默认归属前一天）===
var habitCount = 0;
var habitOffset = -1;                       // 默认记昨天：今早录昨天的执行情况
if (/今天|今日/.test(msgText)) { habitOffset = 0; }
var habitDay = null;                        // ?day=YYYY-MM-DD 可精确补录
if (query.day && /^\d{4}-\d{2}-\d{2}$/.test(String(query.day))) { habitDay = String(query.day); }
function habitStamp() {
  if (habitDay) {
    var hp = habitDay.split('-');
    return Date.UTC(parseInt(hp[0], 10), parseInt(hp[1], 10) - 1, parseInt(hp[2], 10), 12, 0, 0);
  }
  var hd = new Date(ts + habitOffset * 86400000 + 8 * 3600000);
  return Date.UTC(hd.getUTCFullYear(), hd.getUTCMonth(), hd.getUTCDate(), 12, 0, 0); // = 北京 20:00
}
var hts = habitStamp();
var hTags = { session_id: sessionId, source: source };
function pushHabit(meas, fields) {
  measurements.push({ measurement: meas, fields: fields, tags: hTags, timestamp: hts });
  habitCount++;
}
// 睡眠时长：7.5 / 7小时30分 / 7h
var mSleepHM = /(?:睡眠|睡了)\s*(\d+)\s*(?:小时|h)\s*(\d+)\s*分/.exec(msgText);
if (mSleepHM) {
  pushHabit('ppl_habit_sleep', { hours: parseInt(mSleepHM[1], 10) + parseInt(mSleepHM[2], 10) / 60 });
} else {
  var mSleep = /(?:睡眠|睡了)\s*(\d+(?:\.\d+)?)\s*(?:小时|h|hr)?/.exec(msgText);
  if (mSleep) { pushHabit('ppl_habit_sleep', { hours: parseFloat(mSleep[1]) }); }
}
// 有氧：总分钟数
var mCardio = /(?:有氧|跑步|慢跑|单车|动感单车|椭圆机|椭圆|游泳|跳绳)\s*(\d+)\s*(?:分钟|min|分)?/.exec(msgText);
if (mCardio) { pushHabit('ppl_habit_cardio', { minutes: parseInt(mCardio[1], 10) }); }
// 酒精：事件式，喝了几次/几杯；显式说没喝记 0
var mAlc = /(?:喝酒|酒精|酒)\s*(?:(\d+)\s*(?:次|杯|瓶)?|无|没有|没)/.exec(msgText);
if (mAlc) {
  pushHabit('ppl_habit_alcohol', { drinks: mAlc[1] ? parseInt(mAlc[1], 10) : 0 });
} else if (/没喝|未喝|不喝酒|没喝酒/.test(msgText)) {
  pushHabit('ppl_habit_alcohol', { drinks: 0 });
}
// 吸烟：事件式，抽了几支；默认不抽，显式说没抽记 0
var mSmoke = /(?:抽烟|吸烟|香烟|烟)\s*(?:(\d+)\s*(?:支|根|次)?|无|没有|没)/.exec(msgText);
if (mSmoke) {
  pushHabit('ppl_habit_smoke', { cigarettes: mSmoke[1] ? parseInt(mSmoke[1], 10) : 0 });
} else if (/没抽|未抽|不抽烟|没吸烟|不吸烟/.test(msgText)) {
  pushHabit('ppl_habit_smoke', { cigarettes: 0 });
}
// 久坐：达标制 0/1，由自己判断是否做到「每60分钟起身2分钟」
var mSitOk = /久坐\s*(达标|成功|做到|执行|ok|OK|1)/.exec(msgText);
if (mSitOk) {
  pushHabit('ppl_habit_sitting', { ok: 1 });
} else {
  var mSitNo = /久坐\s*(未达标|没做到|失败|否|0)/.exec(msgText);
  if (mSitNo) { pushHabit('ppl_habit_sitting', { ok: 0 }); }
}

// === 感悟解析（识别词：感悟/心得/笔记/reflection；组级/动作级/日级）===
var refWords = ['感悟', '心得', '笔记', 'reflection'];
var refPos = -1;
var refWord = '';
for (var rw = 0; rw < refWords.length; rw++) {
  var rp = msgText.indexOf(refWords[rw]);
  if (rp >= 0 && (refPos === -1 || rp < refPos)) { refPos = rp; refWord = refWords[rw]; }
}
var refCount = 0;
if (refPos >= 0) {
  var refContent = msgText.slice(refPos + refWord.length).replace(/^[\s:：,，。\-—>]+/, '').replace(/\s+$/, '');
  // 动作：取识别词前最近的动作出现（复用 occ 动作扫描结果）
  var refExercise = '';
  var refDir = 'other';
  for (var rk = 0; rk < occ.length; rk++) {
    if (occ[rk].end <= refPos) { refExercise = occ[rk].ex.label; refDir = occ[rk].ex.direction; }
  }
  // 组号：识别词前的"第N组"
  var refSetMatch = /第\s*(\d+)\s*组/.exec(msgText.slice(0, refPos));
  var refSetIndex = refSetMatch ? parseInt(refSetMatch[1], 10) : 0;
  // 日级方向：无动作时从推日/拉日/蹲日推断
  if (!refExercise) {
    var rdScan = /(推日|拉日|蹲日)/g;
    var rdm;
    while ((rdm = rdScan.exec(msgText.slice(0, refPos))) !== null) {
      if (rdm[1] === '推日') { refDir = 'push'; }
      else if (rdm[1] === '拉日') { refDir = 'pull'; }
      else if (rdm[1] === '蹲日') { refDir = 'squat'; }
    }
  }
  // date（本地 UTC+8）与 id（ref_YYYYMMDD_8hex）
  var refDate = new Date(ts + 8 * 3600 * 1000).toISOString().slice(0, 10);
  var refHex = ('00000000' + ts.toString(16)).slice(-8);
  var refId = 'ref_' + refDate.replace(/-/g, '') + '_' + refHex;
  var refTags = { id: refId, date: refDate, source: source, direction: refDir };
  if (refExercise) { refTags.exercise = refExercise; }
  if (refSetIndex > 0) { refTags.set_index = String(refSetIndex); }
  if (sessionId) { refTags.session_id = sessionId; }
  measurements.push({
    measurement: 'ppl_reflection',
    fields: { content: refContent, tags: '' },
    tags: refTags,
    timestamp: ts
  });
  refCount = 1;
  msg.refCount = refCount;
  msg.refExercise = refExercise;
  msg.refSetIndex = refSetIndex;
}

if (measurements.length === 0) {
  msg.payload = { ok: false, message: '未能识别训练数据', detail: msgText };
  msg.statusCode = 400;
  return [null, msg];
}
msg.payload = measurements;
msg.actionCount = actionCount;
msg.setCount = setCount;
msg.isPR = isPR;
msg.durationMin = durTotal;
msg.hrCount = hrCount;
msg.imgCount = imgCount;
msg.habitCount = habitCount;
return [msg, null];

var parts = [];
if (msg.actionCount > 0) { parts.push(msg.actionCount + ' 个' + (msg.isPR ? '动作(PR)' : '动作') + ' ' + msg.setCount + (msg.isPR ? ' 档' : ' 组')); }
if (msg.durationMin > 0) { parts.push('训练时长 ' + msg.durationMin + ' 分钟'); }
if (msg.hrCount > 0) { parts.push(msg.hrCount + ' 条晨脉'); }
if (msg.imgCount > 0) { parts.push('意象训练'); }
if (msg.habitCount > 0) { parts.push(msg.habitCount + ' 条底座习惯'); }
if (msg.refCount > 0) { var rf = msg.refExercise ? ('（' + msg.refExercise + (msg.refSetIndex > 0 ? '·第' + msg.refSetIndex + '组' : '') + '）') : ''; parts.push(msg.refCount + ' 条感悟' + rf); }

if (parts.length === 0) { parts.push('0 项'); }
msg.payload = { ok: true, message: '已记录 ' + parts.join('，') };
